mapper.insert:
INSERT INTO BOOK(
    BOOK_NO
    , MEMBER_NO
    , BOOK_PLACE
    , START_DATE
    , END_DATE
    , BOOK_PURPOSE
    )
VALUES(
    SEQ_BOOK_NO.NEXTVAL
    , #{memberNo}
    , #{bookPlace}
    , TO_DATE(#{startDate}, 'YYYY-MM-DD HH24:MI')
    , TO_DATE(#{endDate}, 'YYYY-MM-DD HH24:MI')
    , #{bookPurpose}
	)

mapper.select:
SELECT COUNT(*)
FROM BOOK B
JOIN MEMBER M ON B.MEMBER_NO = M.NO
WHERE B.CANCEL_DATE IS NULL
AND M.COMPANY_NO = #{companyNo}
AND B.BOOK_PLACE = #{bookPlace}
AND B.START_DATE < TO_DATE(#{endDate}, 'YYYY-MM-DD HH24:MI')
AND B.END_DATE > TO_DATE(#{startDate}, 'YYYY-MM-DD HH24:MI')

	AND B.BOOK_NO != #{bookNo}

mapper.update:
UPDATE BOOK
    SET
        BOOK_PLACE = #{bookPlace}
        , START_DATE = TO_DATE(#{startDate}, 'YYYY-MM-DD HH24:MI')
        , END_DATE = TO_DATE(#{endDate}, 'YYYY-MM-DD HH24:MI')
        , BOOK_PURPOSE = #{bookPurpose}
        , UPDATE_DATE = SYSDATE
WHERE BOOK_NO = #{bookNo}
AND MEMBER_NO = #{memberNo}
AND CANCEL_DATE IS NULL

UPDATE BOOK
    SET
        CANCEL_DATE = SYSDATE
WHERE BOOK_NO = #{bookNo}
AND MEMBER_NO = #{memberNo}
AND CANCEL_DATE IS NULL
